    while ( getIdx(SigPK[t]) ≠ t ) { 
      t = getIdx(SigPK[t]) + 1; 
      PK[t] = XMSS'_keygen(0, t, PK_MT); 
      SigPK[t] = XMSS'_sign(getRoot(PK[t])); 
    } 
    t = t + 1; 
  } 
